import React, { useMemo, useState, useEffect } from 'react';
import { PaginationProps } from './Pagination.types';
import Styled from './Pagination.styles';
import Pages from './components/Pages/Pages';
import QuantityIndicator from './components/QuantityIndicator/QuantityIndicator';
import MobilePagination from './components/MobilePagination/MobilePagination';
import * as Select from '../select';

const Pagination = React.forwardRef(
  (
    {
      current,
      disabled,
      total,
      defaultCurrent = 1,
      pageSize: pageSizeFromProps,
      onChange,
      defaultPageSize,
      showQuantityIndicator = true,
      showPageSizeSelector = true,
      pageSizeOptions = [10, 25, 50],
      quantityIndicatorIntl,
      pageSizeOptionsIntl,
    }: PaginationProps,
    forwardedRef: React.ForwardedRef<HTMLDivElement>
  ): JSX.Element => {
    const getDefaultPageSize = () => {
      if (defaultPageSize) return defaultPageSize;
      return pageSizeOptions[0];
    };

    const [currentPage, setCurrentPage] = useState(current ?? defaultCurrent);
    const [pageSize, setPageSize] = useState(pageSizeFromProps ?? getDefaultPageSize());

    useEffect(() => {
      if (current) {
        setCurrentPage(current);
      }
    }, [current]);

    useEffect(() => {
      if (pageSizeFromProps) {
        setPageSize(pageSizeFromProps);
      }
    }, [pageSizeFromProps]);

    const numberOfPages = useMemo(() => Math.ceil(total / pageSize), [pageSize, total]);

    const handlePageSizeSelect = (option: string) => {
      setPageSize(Number(option));
      const currentNumberOfPages = Math.ceil(total / Number(option));
      if (currentPage > currentNumberOfPages) setCurrentPage(currentNumberOfPages);
      if (onChange && typeof onChange === 'function') {
        onChange(1, Number(option));
      }
    };

    const handlePageChange = (pageNumber: number) => {
      setCurrentPage(pageNumber);
      if (onChange && typeof onChange === 'function') {
        onChange(pageNumber, pageSize);
      }
    };

    const mappedSizeOptions = () => {
      const buildLabel = (option: number) => {
        if (pageSizeOptionsIntl && typeof pageSizeOptionsIntl === 'function') {
          return pageSizeOptionsIntl(option);
        }
        return `Show ${option} items per page`;
      };

      return pageSizeOptions.map((option) => (
        <Select.Option key={option} value={`${option}`}>
          {buildLabel(option)}
        </Select.Option>
      ));
    };

    return (
      <>
        {total === 0 ? (
          <></>
        ) : (
          <Styled.Container ref={forwardedRef} data-testid="pagination-container">
            {showQuantityIndicator && (
              <QuantityIndicator
                total={total}
                pageSize={pageSize}
                currentPage={currentPage}
                numberOfPages={numberOfPages}
                quantityIndicatorIntl={quantityIndicatorIntl}
              />
            )}
            {showPageSizeSelector && (
              <Styled.PageSizeContainer>
                <Select.Root
                  onChange={handlePageSizeSelect}
                  shape="pill"
                  disabled={disabled}
                  size="medium"
                  defaultValue={`${pageSize}`}
                >
                  {mappedSizeOptions()}
                </Select.Root>
              </Styled.PageSizeContainer>
            )}

            <MobilePagination
              currentPage={currentPage}
              disabled={disabled}
              handlePageChange={handlePageChange}
              total={total}
              pageSize={pageSize}
            />

            <Pages
              currentPage={currentPage}
              total={total}
              disabled={disabled}
              handlePageChange={handlePageChange}
              pageSize={pageSize}
            />
          </Styled.Container>
        )}
      </>
    );
  }
);

export default Pagination;
